75	static inline void _list_del(list_node_t *prev, list_node_t *next)
76	{
77	    next->prev = prev;
78	    prev->next = next;
79	}
80	static inline void list_del(list_node_t *entry)
81	{
82	    if (entry->prev != NULL && entry->next != NULL) {
83	        _list_del(entry->prev, entry->next);
84	        entry->prev = NULL;
85	        entry->next = NULL;
86	    }
87	}
