static futex_node_t* get_node(volatile uint64_t *val_addr, int create)
{
    int bucket = futex_hash((uint64_t)val_addr);
    list_head *head = &futex_buckets[bucket];

    /* search the bucket for a node matching this address */
    list_node_t *p;
    for (p = head->next; p != head; p = p->next) {
        futex_node_t *node = list_entry(p, futex_node_t, list);
        if (node->futex_key == (futex_key_t)val_addr) {
            return node;
        }
    }

    if (create) {
        /* allocate and initialize a new node for this address */
        futex_node_t *node = (futex_node_t *)kmalloc(sizeof(futex_node_t));
        node->futex_key = (futex_key_t)val_addr;
        init_list_head(&node->block_queue);
        list_add_tail(&node->list, &futex_buckets[bucket]);
        return node;
    }

    return NULL;
}

void futex_wait(volatile uint64_t *val_addr, uint64_t val)
{
    disable_preempt();

    futex_node_t *node = get_node(val_addr, 1);
    assert(node);
    if (*val_addr == val) {
        /* the value still matches: block until a futex_wakeup */
        do_block(&current_running->list, &node->block_queue);
        scheduler();
    }

    enable_preempt();
}

void futex_wakeup(volatile uint64_t *val_addr, int num_wakeup)
{
    disable_preempt();

    futex_node_t *node = get_node(val_addr, 0);
    if (node != NULL) {
        for (int i = 0; i < num_wakeup; ++i) {
            if (list_empty(&node->block_queue)) {
                break;
            }
            do_unblock(node->block_queue.next);
        }
    }
    scheduler();

    enable_preempt();
}
